DROP TRIGGER IF EXISTS trg_folio_hotel ON "Folio";
CREATE OR REPLACE FUNCTION public.trg_folio_hotel() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW."hotelId" := (SELECT b."hotelId" FROM "Booking" b WHERE b."id" = NEW."bookingId");
  IF NEW."hotelId" IS NULL THEN
    RAISE EXCEPTION 'cannot derive hotelId for Folio: parent row missing' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_folio_hotel BEFORE INSERT OR UPDATE OF "bookingId" ON "Folio" FOR EACH ROW EXECUTE FUNCTION public.trg_folio_hotel();
