END $$;
CREATE TRIGGER trg_folio_transaction_hotel BEFORE INSERT OR UPDATE OF "folioId" ON "FolioTransaction" FOR EACH ROW EXECUTE FUNCTION public.trg_folio_transaction_hotel();
