  IF NEW."hotelId" IS NULL THEN
    RAISE EXCEPTION 'cannot derive hotelId for ScheduledCharge: parent row missing' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_scheduled_charge_hotel BEFORE INSERT OR UPDATE OF "folioId" ON "ScheduledCharge" FOR EACH ROW EXECUTE FUNCTION public.trg_scheduled_charge_hotel();
DROP TRIGGER IF EXISTS trg_room_charge_hotel ON "RoomCharge";
CREATE OR REPLACE FUNCTION public.trg_room_charge_hotel() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW."hotelId" := (SELECT b."hotelId" FROM "BookingRoom" br JOIN "Booking" b ON b."id" = br."bookingId" WHERE br."id" = NEW."bookingRoomId");
  IF NEW."hotelId" IS NULL THEN
    RAISE EXCEPTION 'cannot derive hotelId for RoomCharge: parent row missing' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_room_charge_hotel BEFORE INSERT OR UPDATE OF "bookingRoomId" ON "RoomCharge" FOR EACH ROW EXECUTE FUNCTION public.trg_room_charge_hotel();
